import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Settings — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"settings-01-overview-and-concepts.md","filePath":"settings-01-overview-and-concepts.md"}'),r={name:"settings-01-overview-and-concepts.md"};function o(i,t,d,c,l,h){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="settings-—-overview-concepts" tabindex="-1">Settings — Overview &amp; Concepts <a class="header-anchor" href="#settings-—-overview-concepts" aria-label="Permalink to &quot;Settings — Overview &amp; Concepts&quot;">​</a></h1><p><em>What Settings controls, why it matters, and how changes affect the platform</em></p><hr><h2 id="what-is-the-settings-module" tabindex="-1">What Is the Settings Module? <a class="header-anchor" href="#what-is-the-settings-module" aria-label="Permalink to &quot;What Is the Settings Module?&quot;">​</a></h2><p>Settings is where you configure organization-level behavior in Lodestone. It controls how the platform is identified, who has access, how planning objects behave, and which external systems are connected.</p><p>Every change made in Settings applies globally across the workspace — there are no per-user or per-project overrides for most configuration. This means Settings is one of the highest-leverage areas of the platform: a well-configured workspace produces better AI output, cleaner backlogs, and more consistent planning across the team.</p><hr><h2 id="the-four-settings-sections" tabindex="-1">The Four Settings Sections <a class="header-anchor" href="#the-four-settings-sections" aria-label="Permalink to &quot;The Four Settings Sections&quot;">​</a></h2><p>Settings is organized into four sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it controls</th></tr></thead><tbody><tr><td>Organization</td><td>Workspace identity, description, logo, and archival</td></tr><tr><td>Team</td><td>Member invitations, role assignments, and access management</td></tr><tr><td>Taxonomy</td><td>Custom object type definitions, prefixes, top-tier type, and parent/child type constraints</td></tr><tr><td>Modules</td><td>Strategy defaults, evaluation frameworks, feature status stages, and financial forecast defaults — organized into sub-tabs (Strategy, Features, Financial Forecast)</td></tr><tr><td>Integrations</td><td>Connections to Fireflies, Gong, and JIRA</td></tr></tbody></table><hr><h2 id="roles-and-permissions" tabindex="-1">Roles and Permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and Permissions&quot;">​</a></h2><p>Lodestone has two roles: <strong>Admin</strong> and <strong>Builder</strong>. Admins can do everything in the platform. Builders have access to all planning modules but have specific restrictions in Settings:</p><table tabindex="0"><thead><tr><th>Action</th><th>Admin</th><th>Builder</th></tr></thead><tbody><tr><td>Update organization name, description, and logo</td><td>✓</td><td>✗</td></tr><tr><td>Assign or change member roles</td><td>✓</td><td>✗</td></tr><tr><td>Connect the Gong integration</td><td>✓</td><td>✗</td></tr><tr><td>Create, rename, or delete object types (Taxonomy)</td><td>✓</td><td>✗</td></tr><tr><td>Configure status stages, evaluation criteria, strategy defaults</td><td>✓</td><td>✓</td></tr><tr><td>Assign types to Backlog items</td><td>✓</td><td>✓</td></tr><tr><td>Connect Fireflies and JIRA integrations</td><td>✓</td><td>✓</td></tr><tr><td>Invite and remove team members</td><td>✓</td><td>✓</td></tr></tbody></table><p>There must always be at least one Admin in a workspace — the last Admin cannot be removed or demoted.</p><p>In Settings, Builder restrictions are visually enforced: unavailable fields and sections appear greyed out and non-interactive, with an Admin-required notice displayed. The Features sub-tab under Settings &gt; Modules is hidden entirely for Builders.</p><hr><h2 id="why-settings-matters" tabindex="-1">Why Settings Matters <a class="header-anchor" href="#why-settings-matters" aria-label="Permalink to &quot;Why Settings Matters&quot;">​</a></h2><p>Settings is easy to overlook, but it has a direct impact on planning quality and AI output across the platform:</p><ul><li><strong>Organization Description</strong> — used as context for every AI-generated Document. A rich, accurate description produces more relevant output; a vague one produces generic drafts.</li><li><strong>Status Stages</strong> — define the vocabulary of progress across Features, Releases, and the backlog. Poorly named or incomplete stages create confusion when communicating status to stakeholders.</li><li><strong>Evaluation Criteria</strong> — shape how Features are compared and prioritized. The framework you choose surfaces different signals and drives different conversations.</li><li><strong>Strategy Default</strong> — sets the expected approach for new Strategies, ensuring consistency across the team.</li></ul><hr><h2 id="settings-are-global" tabindex="-1">Settings Are Global <a class="header-anchor" href="#settings-are-global" aria-label="Permalink to &quot;Settings Are Global&quot;">​</a></h2><p>All Settings apply across the entire workspace — they are not per-user, per-roadmap, or per-release. When you change a status stage name, it changes everywhere. When you update the Organization Description, it affects every future document generation. This global scope is intentional: consistency across the team depends on a shared configuration.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for configuring each section of Settings.</em></p>',25)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
